(() => {
  const e2e = (window.__e2e = window.__e2e || {});
  // Shared modules are served under /@fs/<absolute path>; read that URL from a renderer module
  // that imports them, so the helper runs on any checkout.
  e2e.shared = async (name) => {
    e2e.urls = e2e.urls || {};
    if (!e2e.urls[name]) {
      const code = await (await fetch('/engine2d/LandView2D.tsx')).text();
      const found = code.match(new RegExp('"(/@fs/[^"]*/src/shared/' + name + '\\.ts[^"]*)"'));
      e2e.urls[name] = found ? found[1] : null;
    }
    return import(e2e.urls[name]);
  };
  e2e.pos = async () => {
    const p = (await import('/engine/playerProbe.ts')).samplePlayer();
    return p === null ? null : [Math.round(p.x * 10) / 10, Math.round(p.z * 10) / 10];
  };
  // What a player sees of the current chapter: its gate, its people and treasures (world tiles).
  e2e.chapter = async () => {
    const S = await import('/state/index.ts');
    const L = await import('/engine2d/chapterLayer.ts');
    const M = await import('/engine2d/landModel.ts');
    const story = await e2e.shared('story');
    const land = await e2e.shared('land');
    const session = S.useSessionStore.getState();
    const world = S.useWorldStore.getState();
    const landState = S.useLandStore.getState();
    const active = session.activeInstance;
    if (!active || world.scene.status !== 'ready' || !active.cartridge.story) return null;
    const progress = landState.progress;
    const episodes = story.storyEpisodes(active.cartridge.story, progress?.storyMore);
    const next = story.nextEpisode(episodes, progress?.episodes ?? {});
    if (!next) return { cleared: true, episodes: progress?.episodes ?? {} };
    const gate = story.episodeGate(next);
    const stage = progress?.episodes?.[next.id]?.stage ?? null;
    const base = { id: next.id, title: next.title, gate: [gate.x, gate.z], written: stage !== null };
    if (!stage || stage.kind !== 'land') return { ...base, kind: stage?.kind ?? null };
    const draft = L.readChapter(stage.source);
    if (!draft) return { ...base, unreadable: true };
    const seed = land.landSeedOf(active.instance.save);
    const graph = world.scene.value;
    const residents = L.residentTiles ? L.residentTiles(landState.chunks) : new Set();
    const free = (x, z) => !residents.has(x + ',' + z) && M.canStandAt(graph, seed, landState.chunks, x + 0.5, z + 0.5, null);
    const scene = L.chapterScene(next, stage, draft, free);
    return {
      ...base,
      npcs: scene.npcs.map((n) => ({ id: n.id, name: n.name, at: [n.x + 0.5, n.z + 0.5],
        met: stage.met.includes(n.id.split(':')[2]) })),
      treasures: scene.treasures.map((t) => ({ id: t.id, at: [t.x + 0.5, t.z + 0.5],
        found: stage.found.includes(t.id.split(':')[2]) })),
      monsters: scene.monsters.length,
      met: stage.met, found: stage.found,
    };
  };
  // The next thing of the chapter still to do: the nearest unmet person or unopened treasure.
  e2e.nextTodo = async () => {
    const c = await e2e.chapter();
    const at = await e2e.pos();
    if (!c || !c.npcs || !at) return null;
    const todo = [...c.npcs.filter((n) => !n.met), ...c.treasures.filter((t) => !t.found)];
    todo.sort((a, b) => Math.hypot(a.at[0] - at[0], a.at[1] - at[1]) - Math.hypot(b.at[0] - at[0], b.at[1] - at[1]));
    return todo[0] ?? null;
  };
  // Where a player would stand to face it: a free spot next to it from which it, and nothing else
  // (the gate, a neighbour, a resident of the land), is the nearest thing when A is pressed.
  e2e.others = async () => {
    const S = await import('/state/index.ts');
    const c = await e2e.chapter();
    // [x, z, reach]: a gate reaches 0.8 tiles further than a person (engine2d/storyLayer).
    const points = c && c.gate ? [[c.gate[0], c.gate[1], 0.8]] : [];
    if (c && c.npcs) points.push(...c.npcs.map((n) => [...n.at, 0]), ...c.treasures.filter((t) => !t.found).map((t) => [...t.at, 0]));
    for (const [key, chunk] of Object.entries(S.useLandStore.getState().chunks)) {
      if (chunk.status !== 'written') continue;
      const [cx, cz] = key.split(',').map(Number);
      for (const n of chunk.scene.npcs) points.push([cx * 32 + n.x + 0.5, cz * 32 + n.z + 0.5, 0]);
    }
    return points;
  };
  e2e.spot = async () => {
    const t = await e2e.nextTodo();
    const at = await e2e.pos();
    if (!t || !at) return null;
    const S = await import('/state/index.ts');
    const M = await import('/engine2d/landModel.ts');
    const land = await e2e.shared('land');
    const active = S.useSessionStore.getState().activeInstance;
    const graph = S.useWorldStore.getState().scene.value;
    const seed = land.landSeedOf(active.instance.save);
    const chunks = S.useLandStore.getState().chunks;
    const others = (await e2e.others()).filter((p) => Math.hypot(p[0] - t.at[0], p[1] - t.at[1]) > 0.01);
    const spots = [];
    for (const r of [0.8, 1.2]) {
      for (let i = 0; i < 16; i += 1) {
        const a = (i / 16) * Math.PI * 2;
        const p = [t.at[0] + Math.cos(a) * r, t.at[1] + Math.sin(a) * r];
        if (!M.canStandAt(graph, seed, chunks, p[0], p[1], null)) continue;
        const nearestOther = Math.min(...others.map((o) => Math.hypot(o[0] - p[0], o[1] - p[1]) - o[2]));
        if (nearestOther <= r + 0.3) continue;
        spots.push(p);
      }
    }
    spots.sort((a, b) => Math.hypot(a[0] - at[0], a[1] - at[1]) - Math.hypot(b[0] - at[0], b[1] - at[1]));
    return spots[0] ?? t.at;
  };
  e2e.state = async () => {
    const S = await import('/state/index.ts');
    const s = S.useSessionStore.getState();
    const en = S.useEngineStore.getState();
    const layer = [...document.querySelectorAll('[data-layer], [role=dialog]')].filter((l) => l.getClientRects().length > 0).map((l) => l.getAttribute('data-layer') ?? l.getAttribute('role'));
    return {
      screen: s.screen, input: document.documentElement.dataset.input ?? null,
      pos: await e2e.pos(), chunk: en.chunk, nearby: en.nearby && { kind: en.nearby.kind, id: en.nearby.id, label: en.nearby.label },
      locked: en.inputLocked, dialogue: s.dialogue?.status ?? null, speaker: s.dialogueSpeaker,
      episodeOpen: s.episodeOpen, layers: layer,
      focus: document.activeElement && document.activeElement !== document.body ? (document.activeElement.innerText || document.activeElement.getAttribute('aria-label') || document.activeElement.tagName).slice(0, 60) : null,
    };
  };
  return Object.keys(e2e);
})()

